const config = $('Set Configuration Parameters').first().json;
const results = [];
for (const item of $input.all()) {
  const system = item.json.system;
  results.push({
    json: {
      ...system,
      runbookUrl: config.runbookUrl,
      runbookReviewMaxAgeDays: config.runbookReviewMaxAgeDays,
      pillarWeights: config.pillarWeights,
      readinessWarningThreshold: config.readinessWarningThreshold,
      readinessCriticalThreshold: config.readinessCriticalThreshold,
      securityTeamId: config.securityTeamId,
      taskTrackerProjectId: config.taskTrackerProjectId,
      remediationDueDaysCritical: config.remediationDueDaysCritical,
      remediationDueDaysWarning: config.remediationDueDaysWarning
    }
  });
}
return results;

// The Merge node (combine by position, 5 inputs) produces one item per
// input branch per system in n8n's default 'append' style is NOT what we
// want here - so instead this node re-reads each upstream branch directly
// by node name for the current system index, guaranteeing correct pairing
// regardless of merge node behavior/version.
const backupItems = $('Check Backup Job Status').all();
const snapshotItems = $('Check RDS Snapshot Status').all();
const replicationItems = $('Check Replication Health').all();
const iacItems = $('Check IaC / Terraform Drift').all();
const runbookItems = $('Check DR Runbook Last Review').all();
const baseItems = $('Attach Global Config To Each System').all();

const results = [];
for (let i = 0; i < baseItems.length; i++) {
  const base = baseItems[i].json;
  const backup = (backupItems[i] && backupItems[i].json) || {};
  const snapshot = (snapshotItems[i] && snapshotItems[i].json) || {};
  const replication = (replicationItems[i] && replicationItems[i].json) || {};
  const iac = (iacItems[i] && iacItems[i].json) || {};
  const runbook = (runbookItems[i] && runbookItems[i].json) || {};

  const backupBody = backup.body || backup;
  const snapshotBody = snapshot.body || snapshot;
  const replicationBody = replication.body || replication;
  const iacBody = iac.body || iac;
  const runbookBody = runbook.body || runbook;

  const now = Date.now();
  const msPerMin = 60 * 1000;

  const lastBackupTime = backupBody.lastSuccessfulRunAt || backupBody.lastRunAt || null;
  const backupAgeMinutes = lastBackupTime ? Math.round((now - new Date(lastBackupTime).getTime()) / msPerMin) : null;
  const backupLookupSucceeded = lastBackupTime !== null;

  const lastSnapshotTime = snapshotBody.snapshotCreateTime || snapshotBody.createdAt || null;
  const snapshotAgeMinutes = lastSnapshotTime ? Math.round((now - new Date(lastSnapshotTime).getTime()) / msPerMin) : null;
  const snapshotHasCrossRegionCopy = !!(snapshotBody.crossRegionCopyExists || snapshotBody.hasReplicaCopy);
  const snapshotLookupSucceeded = lastSnapshotTime !== null;

  const replicationLagSeconds = typeof replicationBody.replicaLagSeconds === 'number' ? replicationBody.replicaLagSeconds : null;
  const replicationHealthy = replicationBody.status ? String(replicationBody.status).toLowerCase() === 'healthy' : null;
  const replicationLookupSucceeded = replicationLagSeconds !== null || replicationHealthy !== null;

  const iacDriftDetected = !!(iacBody.hasChanges || iacBody['has-changes'] || (iacBody.data && iacBody.data.attributes && iacBody.data.attributes['has-changes']));
  const iacLastRunStatus = iacBody.status || (iacBody.data && iacBody.data.attributes && iacBody.data.attributes.status) || null;
  const iacLookupSucceeded = iacLastRunStatus !== null;

  const runbookLastReviewed = runbookBody.lastModified || runbookBody.lastReviewedAt || null;
  const runbookAgeDays = runbookLastReviewed ? Math.round((now - new Date(runbookLastReviewed).getTime()) / (msPerMin * 60 * 24)) : null;
  const runbookLookupSucceeded = runbookLastReviewed !== null;

  results.push({
    json: {
      ...base,
      backupAgeMinutes,
      backupLookupSucceeded,
      snapshotAgeMinutes,
      snapshotHasCrossRegionCopy,
      snapshotLookupSucceeded,
      replicationLagSeconds,
      replicationHealthy,
      replicationLookupSucceeded,
      iacDriftDetected,
      iacLastRunStatus,
      iacLookupSucceeded,
      runbookAgeDays,
      runbookLookupSucceeded,
      checkedAt: new Date().toISOString()
    }
  });
}

return results;

// Score each DR pillar 0-100 based on policy thresholds, then combine into
// a single weighted DR Readiness Score. Any lookup that failed (fails open)
// is scored as 'Unknown' risk (moderate penalty), never silently treated as
// healthy, so an unreachable monitoring source can't mask a real gap.
const item = $input.item.json;
const weights = item.pillarWeights || { backup: 25, snapshot: 20, replication: 25, iac: 15, runbook: 15 };

function scoreFromAgeRatio(actualMinutes, limitMinutes, lookupSucceeded) {
  if (!lookupSucceeded || actualMinutes === null) return { score: 40, status: 'Unknown - source unreachable' };
  const ratio = actualMinutes / limitMinutes;
  if (ratio <= 0.5) return { score: 100, status: 'Healthy' };
  if (ratio <= 1.0) return { score: 75, status: 'Approaching limit' };
  if (ratio <= 2.0) return { score: 40, status: 'Breached RPO/policy' };
  return { score: 10, status: 'Severely breached' };
}

// --- Backup pillar ---
const backupPillar = scoreFromAgeRatio(item.backupAgeMinutes, item.rpoMinutes, item.backupLookupSucceeded);

// --- Snapshot pillar (RDS-type systems only score meaningfully here) ---
let snapshotPillar;
if (item.type === 'rds') {
  snapshotPillar = scoreFromAgeRatio(item.snapshotAgeMinutes, item.rpoMinutes, item.snapshotLookupSucceeded);
  if (item.requiresCrossRegionReplica && item.snapshotLookupSucceeded && !item.snapshotHasCrossRegionCopy) {
    snapshotPillar = { score: Math.min(snapshotPillar.score, 40), status: snapshotPillar.status + ' + missing cross-region copy' };
  }
} else {
  snapshotPillar = { score: 100, status: 'Not applicable' };
}

// --- Replication pillar ---
let replicationPillar;
if (item.requiresCrossRegionReplica) {
  if (!item.replicationLookupSucceeded) replicationPillar = { score: 40, status: 'Unknown - source unreachable' };
  else if (item.replicationHealthy === false) replicationPillar = { score: 10, status: 'Replication unhealthy' };
  else if (typeof item.replicationLagSeconds === 'number' && item.replicationLagSeconds > 300) replicationPillar = { score: 50, status: `High replication lag (${item.replicationLagSeconds}s)` };
  else replicationPillar = { score: 100, status: 'Healthy' };
} else {
  replicationPillar = { score: 100, status: 'Not required' };
}

// --- IaC pillar ---
let iacPillar;
if (!item.iacLookupSucceeded) iacPillar = { score: 40, status: 'Unknown - source unreachable' };
else if (item.iacDriftDetected) iacPillar = { score: 50, status: 'Drift detected vs live infra' };
else iacPillar = { score: 100, status: 'In sync' };

// --- Runbook pillar ---
const runbookPillar = scoreFromAgeRatio(item.runbookAgeDays, item.runbookReviewMaxAgeDays, item.runbookLookupSucceeded);

const overallScore = Math.round(
  (backupPillar.score * weights.backup +
   snapshotPillar.score * weights.snapshot +
   replicationPillar.score * weights.replication +
   iacPillar.score * weights.iac +
   runbookPillar.score * weights.runbook) /
  (weights.backup + weights.snapshot + weights.replication + weights.iac + weights.runbook)
);

const gaps = [];
if (backupPillar.score < 75) gaps.push({ pillar: 'backup', status: backupPillar.status, score: backupPillar.score });
if (snapshotPillar.score < 75) gaps.push({ pillar: 'snapshot', status: snapshotPillar.status, score: snapshotPillar.score });
if (replicationPillar.score < 75) gaps.push({ pillar: 'replication', status: replicationPillar.status, score: replicationPillar.score });
if (iacPillar.score < 75) gaps.push({ pillar: 'iac', status: iacPillar.status, score: iacPillar.score });
if (runbookPillar.score < 75) gaps.push({ pillar: 'runbook', status: runbookPillar.status, score: runbookPillar.score });

const hasGaps = gaps.length > 0 || overallScore < item.readinessWarningThreshold;

// --- Rolling readiness history via workflow static data ---
const staticData = $getWorkflowStaticData('node');
if (!staticData.historyBySystem) staticData.historyBySystem = {};
if (!staticData.historyBySystem[item.systemId]) staticData.historyBySystem[item.systemId] = [];
staticData.historyBySystem[item.systemId].push({ timestamp: item.checkedAt, overallScore, gapCount: gaps.length });
if (staticData.historyBySystem[item.systemId].length > 30) staticData.historyBySystem[item.systemId].shift();
const recentHistory = staticData.historyBySystem[item.systemId];
const trendDecreasing = recentHistory.length >= 3 && recentHistory[recentHistory.length - 1].overallScore < recentHistory[recentHistory.length - 3].overallScore;

return {
  json: {
    ...item,
    pillarScores: {
      backup: backupPillar,
      snapshot: snapshotPillar,
      replication: replicationPillar,
      iac: iacPillar,
      runbook: runbookPillar
    },
    overallScore,
    gaps,
    hasGaps,
    trendDecreasing,
    recentHistory: recentHistory.slice(-5)
  }
};

// Convert gaps into concrete remediation tasks with priority and due date,
// and determine whether this system's overall condition warrants an urgent
// DR alert versus standard backlog logging.
const item = $input.item.json;

const pillarOwnerHints = {
  backup: 'Platform/Backup Team',
  snapshot: 'Database/RDS Team',
  replication: 'Database/RDS Team',
  iac: 'Infrastructure/Platform Team',
  runbook: 'DR Program Owner'
};

const pillarRemediationText = {
  backup: 'Investigate why the backup job has not completed within RPO; verify scheduler, credentials, and destination storage health.',
  snapshot: 'Verify automated RDS snapshot schedule and cross-region copy configuration; trigger a manual snapshot if needed.',
  replication: 'Investigate replication lag or failure; check network path, replica instance health, and DR-region connectivity.',
  iac: 'Reconcile live infrastructure with Terraform state - either apply pending changes or update IaC to reflect authorized manual changes.',
  runbook: 'Schedule a DR runbook review with the on-call and DR program owner; update procedures and confirm recovery steps still match current architecture.'
};

let overallSeverity = 'Info';
if (item.overallScore < item.readinessCriticalThreshold) overallSeverity = 'Critical';
else if (item.overallScore < item.readinessWarningThreshold) overallSeverity = 'Warning';

const tasks = item.gaps.map(gap => {
  const taskSeverity = gap.score < 40 ? 'Critical' : gap.score < 75 ? 'Warning' : 'Info';
  const dueInDays = taskSeverity === 'Critical' ? item.remediationDueDaysCritical : item.remediationDueDaysWarning;
  const dueDate = new Date(Date.now() + dueInDays * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  return {
    systemId: item.systemId,
    pillar: gap.pillar,
    priority: taskSeverity,
    title: `[DR][${taskSeverity}] ${item.systemId}: ${gap.pillar} gap - ${gap.status}`,
    description: pillarRemediationText[gap.pillar] || 'Review and remediate this DR gap.',
    suggestedOwner: pillarOwnerHints[gap.pillar] || 'Infrastructure Team',
    dueDate,
    projectId: item.taskTrackerProjectId
  };
});

const alertTitle = `${overallSeverity} DR readiness (score ${item.overallScore}/100): ${item.systemId}`;
const alertDescription = `System ${item.systemId} has ${item.gaps.length} gap(s): `
  + item.gaps.map(g => `${g.pillar} (${g.status}, score ${g.score})`).join('; ')
  + `. ${item.trendDecreasing ? 'Readiness trend is declining over recent checks. ' : ''}`
  + `Checked at ${item.checkedAt}.`;

return {
  json: {
    ...item,
    overallSeverity,
    tasks,
    alertTitle,
    alertDescription
  }
};

const items = $input.first().json.data || $input.first().json;
const list = Array.isArray(items) ? items : [items];

const withScores = list.filter(i => typeof i.overallScore === 'number');
const avgScore = withScores.length ? Math.round(withScores.reduce((s, i) => s + i.overallScore, 0) / withScores.length) : null;
const systemsBelowThreshold = withScores.filter(i => i.hasGaps).map(i => ({ systemId: i.systemId, overallScore: i.overallScore, gaps: i.gaps }));

return {
  json: {
    runTimestamp: new Date().toISOString(),
    systemsScanned: withScores.length,
    averageReadinessScore: avgScore,
    systemsWithGaps: systemsBelowThreshold.length,
    systemsBelowThreshold
  }
};
